SELECT id, name, budget FROM departments ORDER BY id;
SELECT COUNT(*) FROM orders;
SELECT COUNT(*), COUNT(city), COUNT(DISTINCT city) FROM customers;
SELECT id, price FROM products WHERE price > 300 ORDER BY price DESC, id;
SELECT status, COUNT(*) FROM orders GROUP BY status ORDER BY status;
SELECT category, COUNT(*), ROUND(AVG(price), 2) FROM products GROUP BY category ORDER BY category;
SELECT id, name FROM customers WHERE city IS NULL ORDER BY id LIMIT 5;
SELECT id, -7 / 2, -7 % 2, 7 / 2.0, 5 / 0 FROM departments WHERE id = 1;
SELECT e.id, e.name, m.name FROM employees e LEFT JOIN employees m ON e.manager_id = m.id ORDER BY e.id LIMIT 8;
SELECT c.city, COUNT(o.id) FROM customers c LEFT JOIN orders o ON o.customer_id = c.id GROUP BY c.city ORDER BY c.city;
SELECT id, name FROM products WHERE name LIKE '%50%%' ORDER BY id;
SELECT id, name FROM products WHERE name LIKE '%deluxe' ORDER BY id LIMIT 6;
SELECT id, name FROM products WHERE name LIKE 'BOOK_1%' ORDER BY id;
SELECT DISTINCT method FROM payments ORDER BY 1;
SELECT o.id, SUM(i.qty * i.unit_price) AS total FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.id ORDER BY total DESC, o.id LIMIT 5;
SELECT customer_id, COUNT(*) AS n FROM orders GROUP BY customer_id HAVING COUNT(*) >= 8 ORDER BY n DESC, customer_id;
SELECT id, CASE WHEN price < 20 THEN 'cheap' WHEN price < 100 THEN 'mid' ELSE 'dear' END FROM products ORDER BY id LIMIT 10;
SELECT id, COALESCE(tier, 0), IFNULL(city, '?') FROM customers ORDER BY id LIMIT 10;
SELECT COUNT(*) FROM orders WHERE customer_id NOT IN (SELECT id FROM customers);
SELECT COUNT(*) FROM order_items WHERE product_id IN (SELECT id FROM products WHERE category = 'game');
SELECT id, name FROM departments d WHERE NOT EXISTS (SELECT 1 FROM employees e WHERE e.dept_id = d.id) ORDER BY id;
SELECT id, (SELECT COUNT(*) FROM reviews r WHERE r.product_id = p.id) AS n FROM products p ORDER BY n DESC, id LIMIT 5;
SELECT UPPER(name), LOWER(name), LENGTH(name) FROM departments ORDER BY id;
SELECT SUBSTR(name, 1, 3), SUBSTR(name, -2), SUBSTR(name, 0, 2) FROM departments ORDER BY id;
SELECT id, ROUND(price), ROUND(price, 1), CAST(price AS INTEGER) FROM products ORDER BY id LIMIT 8;
SELECT id, name || ' (' || category || ')' FROM products ORDER BY id LIMIT 8;
SELECT MIN(day), MAX(day) FROM orders;
SELECT SUM(stock), TOTAL(stock), AVG(stock), SUM(price) FROM products;
SELECT SUM(stock) FROM products WHERE id < 0;
SELECT id FROM customers WHERE tier BETWEEN 2 AND 3 AND city = 'Hue' ORDER BY id LIMIT 10;
SELECT id FROM orders WHERE discount IN (0.05, 0.25) AND status = 'new' ORDER BY id LIMIT 10;
SELECT name FROM departments UNION SELECT city FROM customers WHERE city IS NOT NULL ORDER BY 1;
SELECT dept_id FROM employees UNION ALL SELECT id FROM departments ORDER BY 1 LIMIT 12;
WITH big AS (SELECT order_id, SUM(qty) AS q FROM order_items GROUP BY order_id) SELECT COUNT(*), MAX(q) FROM big;
SELECT id, stars FROM reviews ORDER BY stars, id LIMIT 6;
SELECT id, stars FROM reviews ORDER BY stars DESC, id LIMIT 6;
SELECT p.category, COUNT(DISTINCT o.customer_id) FROM products p JOIN order_items i ON i.product_id = p.id JOIN orders o ON o.id = i.order_id GROUP BY p.category ORDER BY p.category;
SELECT id, REPLACE(name, '_', '-'), INSTR(name, '_') FROM products ORDER BY id LIMIT 6;
SELECT COUNT(*) FROM departments, employees;
SELECT * FROM departments WHERE budget IS NULL OR budget > 400000 ORDER BY id;
